SELECT s.id as scheduleId, d.id as doctorId, d.name as doctorName, d.title as doctorTitle, c.name as departmentName, s.schedule_date as date, s.time_slot as timeSlot, CASE WHEN s.time_slot = 'MORNING' THEN '09:00' WHEN s.time_slot = 'AFTERNOON' THEN '14:00' WHEN s.time_slot = 'EVENING' THEN '18:00' ELSE '09:00' END as startTime, CASE WHEN s.time_slot = 'MORNING' THEN '12:00' WHEN s.time_slot = 'AFTERNOON' THEN '17:00' WHEN s.time_slot = 'EVENING' THEN '21:00' ELSE '12:00' END as endTime, s.available_slots as availableSlots, s.total_slots as totalSlots, s.slot_type as slotType FROM schedule s LEFT JOIN doctor d ON s.doctor_id = d.id LEFT JOIN clinic c ON d.clinic_id = c.id WHERE s.schedule_date >= #{startDate} AND s.schedule_date <= #{endDate} AND s.available_slots > 0
AND s.id != #{excludeScheduleId}
AND c.id = #{departmentId}
AND s.doctor_id = #{doctorId}
AND s.time_slot = #{timeSlot}
ORDER BY s.schedule_date, s.time_slot

SELECT s.id, s.doctor_id as doctorId, d.name as doctorName, dept.id as departmentId, dept.name as departmentName, c.id as clinicId, c.name as clinicName, s.schedule_date as scheduleDate, s.time_slot as timeSlot, s.slot_type as slotType, s.total_slots as totalSlots, s.available_slots as availableSlots FROM schedule s LEFT JOIN doctor d ON s.doctor_id = d.id LEFT JOIN clinic c ON d.clinic_id = c.id LEFT JOIN department dept ON c.department_id = dept.id
AND s.doctor_id = #{doctorId}
AND dept.id = #{departmentId}
AND s.schedule_date >= #{startDate}
AND s.schedule_date <= #{endDate}
AND s.time_slot = #{timeSlot}
AND s.slot_type = #{slotType}
ORDER BY s.schedule_date DESC, s.time_slot

SELECT COUNT(*)
FROM schedule s

    LEFT JOIN doctor d ON s.doctor_id = d.id



        AND s.doctor_id = #{doctorId}


        AND d.clinic_id = #{departmentId}


        AND s.schedule_date >= #{startDate}


        AND s.schedule_date <= #{endDate}


        AND s.time_slot = #{timeSlot}


        AND s.slot_type = #{slotType}

SELECT SUM(s.total_slots) FROM schedule s

    LEFT JOIN doctor d ON s.doctor_id = d.id
    LEFT JOIN clinic c ON d.clinic_id = c.id



        c.department_id = #{departmentId}


        AND s.schedule_date >= #{startDate}


        AND s.schedule_date <= #{endDate}

SELECT SUM(s.available_slots) FROM schedule s

    LEFT JOIN doctor d ON s.doctor_id = d.id
    LEFT JOIN clinic c ON d.clinic_id = c.id



        c.department_id = #{departmentId}


        AND s.schedule_date >= #{startDate}


        AND s.schedule_date <= #{endDate}

SELECT s.* FROM schedule s
LEFT JOIN doctor d ON s.doctor_id = d.id
LEFT JOIN clinic c ON d.clinic_id = c.id

    s.available_slots > 0
    AND s.schedule_date >= DATE_SUB(#{originalDate}, INTERVAL 7 DAY)
    AND s.schedule_date <= DATE_ADD(#{originalDate}, INTERVAL 30 DAY)



            AND s.doctor_id = #{doctorId}
            AND s.schedule_date = #{originalDate}
            AND s.time_slot != #{timeSlot}



            AND s.doctor_id = #{doctorId}



            AND c.id = #{clinicId}
            AND d.title = #{titleLevel}
            AND s.doctor_id != #{doctorId}



            AND c.id = #{clinicId}
            AND s.doctor_id != #{doctorId}



ORDER BY
    ABS(DATEDIFF(s.schedule_date, #{originalDate})) ASC,
    CASE
        WHEN s.time_slot = #{timeSlot} THEN 1
        WHEN s.schedule_date = #{originalDate} THEN 2
        ELSE 3
    END ASC,
    CASE s.time_slot
        WHEN 'MORNING' THEN 1
        WHEN 'AFTERNOON' THEN 2
        WHEN 'EVENING' THEN 3
        ELSE 4
    END ASC
LIMIT 1

SELECT * FROM schedule
WHERE doctor_id = #{doctorId}
  AND schedule_date = #{scheduleDate}
  AND time_slot = #{timeSlot}
LIMIT 1
